// Merging Locales: Copy base_loc, override facets for specified category (CAT) 
// using facets found in the named locale "de_DE.UTF-8".

std::locale base_loc("C");
std::locale::category CAT = std::locale::numeric;

std::locale merged_loc(
    base_loc, 
    "de_DE.UTF-8", 
    CAT
);

// merged_loc now uses "C" locale settings, except for 
// numeric formatting (thousands separators, decimal point) 
// which follow German conventions.
